interface WashType{String getName();int getDurationMinutes();double getCharge();}
class QuickWash implements WashType{public String getName(){return "Quick";}public int getDurationMinutes(){return 30;}public double getCharge(){return 20;}}
class NormalWash implements WashType{public String getName(){return "Normal";}public int getDurationMinutes(){return 45;}public double getCharge(){return 30;}}
class HeavyWash implements WashType{public String getName(){return "Heavy";}public int getDurationMinutes(){return 60;}public double getCharge(){return 45;}}
class Student{private final String name;public Student(String n){if(n==null||n.trim().isEmpty())throw new IllegalArgumentException();name=n;}public String getName(){return name;}}
class WashCycle{private final Student student;private final WashingMachine machine;private final WashType type;private boolean completed;WashCycle(Student s,WashingMachine m,WashType t){if(s==null||m==null||t==null)throw new IllegalArgumentException();student=s;machine=m;type=t;}public Student getStudent(){return student;}public WashType getWashType(){return type;}public int getDurationMinutes(){return type.getDurationMinutes();}public double getCharge(){return type.getCharge();}void complete(){completed=true;}public boolean isCompleted(){return completed;}}
class WashingMachine{private final String id;private WashCycle cycle;public WashingMachine(String i){if(i==null||i.trim().isEmpty())throw new IllegalArgumentException();id=i;}public String getMachineId(){return id;}public boolean isFree(){return cycle==null;}public WashCycle startWash(Student s,WashType t){if(cycle!=null)return null;cycle=new WashCycle(s,this,t);return cycle;}public WashCycle completeCycle(){WashCycle c=cycle;cycle=null;if(c!=null)c.complete();return c;}}
public class LaundrySystem{public static String startWash(Student s,WashingMachine m,WashType t){WashCycle c=m.startWash(s,t);if(c==null)return "Machine "+m.getMachineId()+" is currently busy.";return t.getName()+" wash started on "+m.getMachineId()+" for "+s.getName()+" ("+t.getDurationMinutes()+" min). Charge: ₹"+String.format("%.2f",t.getCharge());}public static String completeWash(WashingMachine m){WashCycle c=m.completeCycle();return c==null?"Machine "+m.getMachineId()+" is already free.":m.getMachineId()+" cycle completed. "+m.getMachineId()+" is now free.";}}
